import { createBillingPortal } from "@/lib/billing/checkout";
import {
  billingHttpError,
  limitBillingRequest,
  billingSessionUser,
  privateBillingHeaders,
  requireBillingOrigin,
} from "@/lib/billing/http";

export const runtime = "nodejs";
export async function POST(request: Request) {
  try {
    const userId = await billingSessionUser();
    requireBillingOrigin(request);
    await limitBillingRequest(userId, "portal");
    return Response.json(await createBillingPortal(userId), {
      headers: privateBillingHeaders,
    });
  } catch (error) {
    return billingHttpError(error);
  }
}
